package com.pompomhills.intelligence.workflow;

import com.pompomhills.intelligence.quality.QualityMlClient;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.*;
import static com.pompomhills.intelligence.workflow.CpqOwnerPilotService.*;

/** A diagnostic purpose in the existing immutable CPQ ledger. Never production admission evidence. */
@Service
public class CpqDraftReviewService {
  static final String PURPOSE="DRAFT_COMPARATIVE_REVIEW_V1",INSTRUCTION="PAIRWISE_CREATIVE_INSTRUCTIONS_V2",SCHEMA="PAIRWISE_CREATIVE_RESPONSE_V1";
  static final List<String> DIMS=List.of("SCROLL_STOP_VISUAL_PROMISE","CAUSAL_PROGRESSION","VISUAL_STORYTELLING","PRODUCTION_EXECUTABILITY","ENDING_REPLAY","DISTINCTIVE_CREATIVE_VALUE");
  static final Set<String> JUDGMENTS=Set.of("A_BETTER","B_BETTER","EQUIVALENT","INSUFFICIENT_EVIDENCE");
  final JdbcClient db;final CpqOwnerPilotService util;final CreativePromptQualityService cpq;final QualityMlClient ml;
  @Value("${pompom.cpq-pilot.real-enabled:false}") boolean realEnabled;
  public CpqDraftReviewService(JdbcClient db,CpqOwnerPilotService util,CreativePromptQualityService cpq,QualityMlClient ml){this.db=db;this.util=util;this.cpq=cpq;this.ml=ml;}
  Map<String,Object> spec(){try{return util.read(new ClassPathResource("cpq/mimi-draft-comparison-v1.json").getContentAsString(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException("Bound draft resource unavailable");}}
  Map<String,Object> snapshot(){
    var spec=spec();var original=cpq.pilotSubject(uuid(spec.get("analysisId")),null,null);
    String prompt=String.valueOf(original.get("promptText")),draft=String.valueOf(spec.get("draftText"));
    if(!hash(prompt).equals(spec.get("originalSha256")) || !hash(draft).equals(spec.get("draftSha256")) || !Objects.equals(original.get("approvedStorySha256"),spec.get("approvedStorySha256")) || !hash(String.valueOf(map(original.get("approvedStory")).get("text"))).equals(spec.get("approvedStorySha256")))throw new ResponseStatusException(CONFLICT,"Exact persisted original, draft or story fingerprint differs; no substitution");
    var production=map(original.get("productionSettings"));var context=map(spec.get("effectiveProductionContext"));var nested=map(production.get("settings"));
    for(String key:List.of("contentProfile","generator"))if(!Objects.equals(production.get(key),context.get(key)))throw new ResponseStatusException(CONFLICT,"Production context changed");
    if(((Number)production.get("desiredDuration")).intValue()!=15 || !Objects.equals(nested.get("aspectRatio"),"9:16") || !Objects.equals(nested.get("mode"),"image2video") || !Objects.equals(nested.get("resolution"),"480p"))throw new ResponseStatusException(CONFLICT,"Production settings changed");
    var inputs=new LinkedHashMap<String,Object>();for(String slot:List.of("CRITIC_A","CRITIC_B"))inputs.put(slot,Map.of("purpose",PURPOSE,"instructionVersion",INSTRUCTION,"responseSchemaVersion",SCHEMA,"reviewerInstructions",spec.get("reviewerInstructions"),"productionSettings",context,"packets",slot.equals("CRITIC_A")?List.of(Map.of("label","A","prompt",draft),Map.of("label","B","prompt",prompt)):List.of(Map.of("label","B","prompt",prompt),Map.of("label","A","prompt",draft))));
    var out=new LinkedHashMap<String,Object>();out.put("purpose",PURPOSE);out.put("analysisId",spec.get("analysisId"));out.put("productionSettings",production);out.put("approvedStory",original.get("approvedStory"));out.put("approvedStorySha256",original.get("approvedStorySha256"));out.put("inputs",inputs);out.put("instructionVersion",INSTRUCTION);out.put("responseSchemaVersion",SCHEMA);out.put("preparedPacketSha256",spec.get("preparedPacketSha256"));out.put("draftArtifactSha256",spec.get("draftArtifactSha256"));
    out.put("supervisorMapping",Map.of("A",Map.of("subjectType","DEVELOPMENT_DRAFT","status","DRAFT_ONLY","sha256",spec.get("draftSha256"),"provenance",spec.get("draftProvenance")),"B",Map.of("subjectType","ORIGINAL","status","IMMUTABLE_PROMPT_10_VERSION_1","sha256",spec.get("originalSha256"),"sourceIdentity",original.get("sourceIdentity"))));
    out.put("limitations",List.of("DIAGNOSTIC_ONLY","Original source verdict FAIL; draft fidelity UNKNOWN; neither sent to critics","Prompt wording may reveal provenance; no perfect blindness","Not source PASS, prompt approval, official grade or render permission"));return out;
  }
  static String profileFor(String slot){if("CRITIC_A".equals(slot))return "deepseek-primary";if("CRITIC_B".equals(slot))return "openai-escalation";throw new ResponseStatusException(BAD_REQUEST,"Exact diagnostic critic slot required");}
  Map<String,Object> cost(Map<String,Object> scope,String slot){return ml.workflow("cpq-pilot/draft-preflight",Map.of("profileId",profileFor(slot),"input",map(scope.get("inputs")).get(slot)));}
  public Map<String,Object> preflight(HttpServletRequest r){util.owner(r);var scope=snapshot();return Map.of("purpose",PURPOSE,"persisted",false,"scopeSha256",hash(util.encode(scope)),"snapshot",scope,"reviewers",Map.of("CRITIC_A",cost(scope,"CRITIC_A"),"CRITIC_B",cost(scope,"CRITIC_B")),"realDispatchEnabled",realEnabled,"diagnosticOnly",true);}
  @Transactional public Map<String,Object> create(Map<String,Object> body,HttpServletRequest r){
    var scope=snapshot();String owner=util.owner(r);if(!Boolean.TRUE.equals(body.get("authorizeDiagnosticRecordCreation")) || !Boolean.TRUE.equals(body.get("confirmDiagnosticOnly")) || !Objects.equals(body.get("scopeSha256"),hash(util.encode(scope))))throw new ResponseStatusException(BAD_REQUEST,"Explicit creation consent and exact scope required");
    double budget=money(body.get("maxTotalUsd"));UUID id=UUID.randomUUID();
    db.sql("INSERT INTO cpq_owner_pilots(pilot_id,owner_principal,policy_version,scope_sha256,snapshot,total_budget_usd) VALUES(:id,:owner,:policy,:hash,CAST(:scope AS jsonb),:budget)").param("id",id).param("owner",owner).param("policy",PURPOSE).param("hash",hash(util.encode(scope))).param("scope",util.encode(scope)).param("budget",budget).update();return view(id,r);
  }
  Map<String,Object> record(UUID id,HttpServletRequest r,boolean fresh){String owner=util.owner(r);var row=db.sql("SELECT owner_principal,snapshot::text,scope_sha256,total_budget_usd FROM cpq_owner_pilots WHERE pilot_id=:id AND policy_version=:policy").param("id",id).param("policy",PURPOSE).query((rs,n)->Map.<String,Object>of("owner",rs.getString(1),"snapshot",util.read(rs.getString(2)),"scopeSha256",rs.getString(3),"budget",rs.getDouble(4))).optional().orElseThrow(()->new ResponseStatusException(NOT_FOUND,"Diagnostic review not found"));if(!owner.equals(row.get("owner")))throw new ResponseStatusException(FORBIDDEN,"Diagnostic review owner differs");if(fresh && !hash(util.encode(snapshot())).equals(row.get("scopeSha256")))throw new ResponseStatusException(CONFLICT,"Diagnostic source/context is stale");return row;}
  public Map<String,Object> view(UUID id,HttpServletRequest r){var record=record(id,r,false);var requests=db.sql("SELECT request_id,slot,state,authorization_payload::text,response::text,failure FROM cpq_machine_requests WHERE pilot_id=:id ORDER BY created_at,request_id").param("id",id).query((rs,n)->{var v=new LinkedHashMap<String,Object>();v.put("requestId",rs.getString(1));v.put("slot",rs.getString(2));v.put("state",rs.getString(3));v.put("authorization",util.read(rs.getString(4)));v.put("response",util.read(Objects.toString(rs.getString(5),"{}")));v.put("failure",Objects.toString(rs.getString(6),""));return v;}).list();
    var evidence=db.sql("SELECT evidence_id,payload::text FROM cpq_pilot_evidence WHERE pilot_id=:id ORDER BY created_at,evidence_id").param("id",id).query((rs,n)->Map.of("evidenceId",rs.getString(1),"payload",util.read(rs.getString(2)))).list();
    return Map.of("reviewId",id.toString(),"purpose",PURPOSE,"snapshot",record.get("snapshot"),"requests",requests,"evidence",evidence,"diagnosticOnly",true,"sourceFidelity","UNRESOLVED_NOT_EVALUATED_BY_THIS_REVIEW","officialGrading","INACTIVE","renderAuthorized",false,"humanReviewCount",0);
  }
  @Transactional public Map<String,Object> authorize(UUID id,Map<String,Object> body,HttpServletRequest r){
    var record=record(id,r,true);db.sql("SELECT pilot_id FROM cpq_owner_pilots WHERE pilot_id=:id FOR UPDATE").param("id",id).query(UUID.class).single();String slot=String.valueOf(body.get("slot"));var estimate=cost(map(record.get("snapshot")),slot);
    if(!Boolean.TRUE.equals(body.get("authorizePaidInference")) || !Boolean.FALSE.equals(body.get("automaticRetries")) || !Boolean.TRUE.equals(body.get("confirmDiagnosticOnly")) || !Objects.equals(body.get("scopeSha256"),record.get("scopeSha256")) || !profileFor(slot).equals(body.get("profileId")))throw new ResponseStatusException(BAD_REQUEST,"Explicit bound diagnostic single-call authorization required");
    for(String key:List.of("provider","model","reasoningEffort","maxOutputTokens"))if(!Objects.equals(body.get(key),estimate.get(key)))throw new ResponseStatusException(CONFLICT,"Exact configured diagnostic model/limits required: "+key);
    var caps=ml.workflow("cpq-pilot/capabilities",Map.of());if(!Boolean.TRUE.equals(map(map(caps.get("profiles")).get(profileFor(slot))).get("configured")))throw new ResponseStatusException(CONFLICT,"Reviewer provider key unavailable");
    double cap=money(body.get("maxCostUsd"));if(cap<((Number)estimate.get("maxCalculatedCostUsd")).doubleValue())throw new ResponseStatusException(CONFLICT,"Insufficient bounded diagnostic budget");
    String key=String.valueOf(body.getOrDefault("idempotencyKey",""));if(key.length()<16 || key.length()>100)throw new ResponseStatusException(BAD_REQUEST,"Durable idempotency key required");
    var prior=db.sql("SELECT authorization_payload::text FROM cpq_machine_requests WHERE pilot_id=:id AND idempotency_key=:key").param("id",id).param("key",key).query(String.class).optional();if(prior.isPresent()){if(!util.encode(util.read(prior.get())).equals(util.encode(body)))throw new ResponseStatusException(CONFLICT,"Different authorization for idempotency key");return view(id,r);}
    if(db.sql("SELECT count(*) FROM cpq_machine_requests WHERE pilot_id=:id AND slot=:slot").param("id",id).param("slot",slot).query(Integer.class).single()>0)throw new ResponseStatusException(CONFLICT,"Diagnostic slot already reserved; no retry");
    double reserved=db.sql("SELECT coalesce(sum(reserved_usd),0) FROM cpq_machine_requests WHERE pilot_id=:id").param("id",id).query(Double.class).single();if(reserved+cap>((Number)record.get("budget")).doubleValue()+1e-9)throw new ResponseStatusException(CONFLICT,"Combined authorized ceiling exceeded");
    var input=map(map(record.get("snapshot")).get("inputs")).get(slot);UUID request=UUID.randomUUID();db.sql("INSERT INTO cpq_machine_requests(request_id,pilot_id,slot,idempotency_key,authorized_by,authorization_payload,input_sha256,state,reserved_usd,input) VALUES(:request,:id,:slot,:key,:owner,CAST(:auth AS jsonb),:hash,'AUTHORIZED',:cap,CAST(:input AS jsonb))").param("request",request).param("id",id).param("slot",slot).param("key",key).param("owner",util.owner(r)).param("auth",util.encode(body)).param("hash",hash(util.encode(input))).param("cap",cap).param("input",util.encode(input)).update();return view(id,r);
  }
  // Durable CAS commits before transport, same as the existing production pilot. Never transaction-wrap inference.
  public Map<String,Object> execute(UUID id,UUID request,HttpServletRequest r){
    var record=record(id,r,true);if(!realEnabled)throw new ResponseStatusException(FORBIDDEN,"Real diagnostic dispatch disabled");
    var row=db.sql("SELECT slot,state,input::text,authorization_payload::text,input_sha256 FROM cpq_machine_requests WHERE pilot_id=:id AND request_id=:request").param("id",id).param("request",request).query((rs,n)->Map.<String,Object>of("slot",rs.getString(1),"state",rs.getString(2),"input",util.read(rs.getString(3)),"authorization",util.read(rs.getString(4)),"inputSha256",rs.getString(5))).optional().orElseThrow(()->new ResponseStatusException(NOT_FOUND,"Diagnostic request not found"));
    if(!"AUTHORIZED".equals(row.get("state")))return view(id,r);
    if(!Objects.equals(hash(util.encode(row.get("input"))),row.get("inputSha256")) || !util.encode(row.get("input")).equals(util.encode(map(map(record.get("snapshot")).get("inputs")).get(row.get("slot")))))throw new ResponseStatusException(CONFLICT,"Immutable diagnostic request differs");
    if("CRITIC_B".equals(row.get("slot")) && db.sql("SELECT count(*) FROM cpq_machine_requests WHERE pilot_id=:id AND slot='CRITIC_A' AND state='COMPLETED'").param("id",id).query(Integer.class).single()!=1)throw new ResponseStatusException(CONFLICT,"First critic must complete; stop remaining dispatch on failure");
    int changed=db.sql("UPDATE cpq_machine_requests SET state='DISPATCHING' WHERE request_id=:request AND state='AUTHORIZED' AND pg_try_advisory_xact_lock(hashtext(:scope)) AND NOT EXISTS(SELECT 1 FROM cpq_machine_requests other WHERE other.pilot_id=:id AND other.state IN ('DISPATCHING','FAILED_OR_AMBIGUOUS'))").param("request",request).param("scope",id.toString()).param("id",id).update();if(changed!=1)throw new ResponseStatusException(CONFLICT,"Diagnostic dispatch/failure blocks remaining calls; inspect saved state");
    try{
      var response=ml.workflow("cpq-pilot/execute",Map.of("requestId",request.toString(),"input",row.get("input"),"authorization",row.get("authorization")));
      db.sql("UPDATE cpq_machine_requests SET response=CAST(:response AS jsonb) WHERE request_id=:request AND state='DISPATCHING'").param("response",util.encode(response)).param("request",request).update();
      validateResponse(map(row.get("input")),map(row.get("authorization")),request,response);
      var payload=Map.of("reviewPurpose",PURPOSE,"diagnosticOnly",true,"requestId",request.toString(),"slot",row.get("slot"),"inputSha256",row.get("inputSha256"),"response",response,"validationOutcome","ACCEPTED_DIAGNOSTIC_ONLY","supervisorMapping",map(record.get("snapshot")).get("supervisorMapping"));
      db.sql("WITH done AS (UPDATE cpq_machine_requests SET state='COMPLETED',completed_at=now() WHERE request_id=:request AND state='DISPATCHING' RETURNING request_id) INSERT INTO cpq_pilot_evidence(evidence_id,pilot_id,request_id,evidence_type,actor,payload) SELECT :evidence,:id,request_id,'MACHINE_REVIEW',:actor,CAST(:payload AS jsonb) FROM done").param("request",request).param("evidence",UUID.randomUUID()).param("id",id).param("actor",response.get("provider")+":"+response.get("model")).param("payload",util.encode(payload)).update();
    }catch(Exception failure){db.sql("UPDATE cpq_machine_requests SET state='FAILED_OR_AMBIGUOUS',failure='Diagnostic dispatch or response failed; inspect retained response, no retry',completed_at=now() WHERE request_id=:request AND state='DISPATCHING'").param("request",request).update();}
    return view(id,r);
  }
  void validateResponse(Map<String,Object> input,Map<String,Object> auth,UUID request,Map<String,Object> response){
    if(!PURPOSE.equals(response.get("reviewPurpose")) || !Boolean.TRUE.equals(response.get("diagnosticOnly")) || !"COMPLETED".equals(response.get("executionStatus")) || !"MACHINE_REVIEW".equals(response.get("evidenceType")) || !request.toString().equals(response.get("requestId")) || !Objects.equals(auth.get("provider"),response.get("provider")) || !Objects.equals(auth.get("model"),response.get("model")) || !"stop".equals(map(response.get("providerMetadata")).get("finishReason")) || !"COMPLETE".equals(response.get("usageAccountingStatus")) || !(response.get("costUsd") instanceof Number cost) || !Double.isFinite(cost.doubleValue()) || cost.doubleValue()<0 || cost.doubleValue()>((Number)auth.get("maxCostUsd")).doubleValue())throw new IllegalArgumentException("Complete bounded diagnostic provenance required");
    var metadata=map(response.get("providerMetadata"));var usage=map(response.get("usage"));var effective=map(response.get("effectiveRequestConfiguration"));
    if(!"COMPLETED".equals(metadata.get("apiStatus")) || !Objects.equals(auth.get("model"),metadata.get("model")) || String.valueOf(metadata.getOrDefault("requestId","")).isBlank() || !(usage.get("prompt_tokens") instanceof Number in) || in.longValue()<0 || !(usage.get("completion_tokens") instanceof Number out) || out.longValue()<0 || out.longValue()>((Number)auth.get("maxOutputTokens")).longValue())throw new IllegalArgumentException("Actual bounded provider accounting required");
    for(String key:List.of("provider","model","reasoningEffort","maxOutputTokens"))if(!Objects.equals(auth.get(key),effective.get(key)))throw new IllegalArgumentException("Effective diagnostic configuration differs");
    var comparison=map(response.get("comparison"));if(!(response.get("rawResponse") instanceof String raw) || !util.encode(util.read(raw)).equals(util.encode(comparison)))throw new IllegalArgumentException("Raw comparative conclusions must remain exact");
    var dimensions=map(comparison.get("dimensions"));if(!dimensions.keySet().equals(new HashSet<>(DIMS)))throw new IllegalArgumentException("All six pairwise dimensions required");var prompts=new HashMap<String,String>();for(var p:rows(input.get("packets")))prompts.put(String.valueOf(p.get("label")),String.valueOf(p.get("prompt")));
    for(var value:dimensions.values()){var d=map(value);if(!JUDGMENTS.contains(d.get("judgment")) || String.valueOf(d.getOrDefault("reason","")).strip().length()<20 || String.valueOf(d.getOrDefault("uncertainty","")).isBlank())throw new IllegalArgumentException("Pairwise judgment/reason/uncertainty required");var evidence=rows(d.get("evidence"));var labels=new HashSet<Object>();for(var q:evidence){String quote=String.valueOf(q.getOrDefault("quote",""));if(quote.isBlank() || !prompts.getOrDefault(q.get("label"),"").contains(quote))throw new IllegalArgumentException("Cross-prompt or fabricated quotation");labels.add(q.get("label"));}if((evidence.isEmpty() || (Set.of("A_BETTER","B_BETTER").contains(d.get("judgment")) && labels.size()!=2)) && String.valueOf(d.getOrDefault("absentEvidenceExplanation","")).strip().length()<20)throw new IllegalArgumentException("Missing evidence requires explanation");}
    var overall=map(comparison.get("overall"));if(!JUDGMENTS.contains(overall.get("judgment")))throw new IllegalArgumentException("Overall pairwise result required");for(String k:List.of("rationale","strongestDifference","unresolvedIssue","uncertainty"))if(String.valueOf(overall.getOrDefault(k,"")).isBlank())throw new IllegalArgumentException("Incomplete overall comparison");
  }
}
